--region handler
function CardProgressionEquipmentChooseDialog:OnEventOperateEquipOrCore(params, equipType, direction)
    if direction ~= 2 then return end
    
    local dojo = checkTable(params.dojo)
    local part = params.part
    local id   = checkInt(dojo.id)
    local equipList = self:GetEquipmentList()
    local animData = clone(equipList)
    if checkInt(equipList[part]) == id then
        equipList[part] = 0
    else
        equipList[part] = id
    end
    
    self:RefreshEquipmentNodeWithAnim(animData)
    
end

