---保存新套装按钮点击回调
function CardProgressionEquipmentChooseDialog:BtnSaveNewOnClickHandler()
    if EquipUtils.CheckEquipmentPresetLimit() then
        GameUtils.Toast(localize("装备预设已达上限"))
        return
    end
    
    if not self:IsSuitAvailable() then return end

    local name = self.InputField.text
    local equipmentStr = self:GetFormattingEquipmentStr()
    GameUtils.Request(Interfaces.OverseaEquipmentSaveDiySuit, {name = name, equipments = equipmentStr}, function (request,response)
        if checkNumber(response.errCode) ~= 0 then return end

        -- 更新本地数据
        local equipmentDiySuits = checkTable(PlayerComponent.playerDojo.equipmentDiySuits)
        local temp = {
            suitId = checkInt(response.data.suitId),
            name = name,
            equipments = equipmentStr,
        }
        table.insert(equipmentDiySuits, temp)
        Events.Broadcast(Constants.EventNames.EquipmentPresetDialogUpdate)
        GameUtils.Toast(localize("保存成功"))
        CfUtils.DialogBack()
    end)
end

---保存按钮点击回调
function CardProgressionEquipmentChooseDialog:BtnSaveOnClickHandler()
    if not self:IsSuitAvailable() then return end
    
    local suitData = self:GetSuitData()
    local suitId = checkInt(suitData.suitId)
    local name = self.InputField.text
    local equipmentStr = self:GetFormattingEquipmentStr()
    GameUtils.Request(Interfaces.OverseaEquipmentSaveDiySuit, {suitId = suitId, name = name, equipments = equipmentStr}, function (request,response)
        if checkNumber(response.errCode) ~= 0 then return end

        -- 更新本地数据
        local equipmentDiySuits = checkTable(PlayerComponent.playerDojo.equipmentDiySuits)
        for _, v in ipairs(equipmentDiySuits) do
            if checkInt(v.suitId) == suitId then
                v.name = name
                v.equipments = equipmentStr
                break
            end
        end
        Events.Broadcast(Constants.EventNames.EquipmentPresetDialogUpdate)
        GameUtils.Toast(localize("保存成功"))
        CfUtils.DialogBack()
    end)
end

