function CardProgressionEquipmentChooseDialog:BtnEquipmentOnClickHandler(part)
    if self.part ~= part then
        self:RefreshEquipBtnSelectState(self.part, false)
        self:RefreshEquipBtnSelectState(part, true)
        self.part = part
    end

    -- 页签切换
    local mbEnv = self:GetEquipmentListEnv()
    if mbEnv == nil then return end
    mbEnv:SwitchPart(part)

    local equipId = self:GetEquipmentList()[part]
    if checkInt(equipId) ~= 0 then
        -- 装备详情
        local curDojo = EquipComponent:GetEquipById(equipId)
        self:LoadComparedView(curDojo, nil, 2, part, Bind(self, self.HideSelectIndex))
    end
end

function CardProgressionEquipmentChooseDialog:OnCellClickAction(backpackDataId, part, equipType, index)
    if backpackDataId <= 0 then return end
    local equipIdList = self:GetEquipmentList()
    local equipPart = part or self.part
    local curDojo = EquipComponent:GetEquipById(equipIdList[equipPart])
    local compareDojo = EquipComponent:GetEquipById(backpackDataId)
    if curDojo and checkInt(curDojo.id) == checkInt(compareDojo.id) then
        compareDojo = nil
    end

    self:LoadComparedView(curDojo, compareDojo, equipType, equipPart, Bind(self, self.HideSelectIndex))
end

function CardProgressionEquipmentChooseDialog:OnUpdatePartAction(part)
    self:SwitchPart(part)
end
