function CardProgressionEquipmentChooseDialog:RefreshEquipmentNodeWithAnim(animData)
    self:StopAniCo()
    self._aniCo = cs_coroutine.start(function()
        local equipmentList = self:GetEquipmentList()
        local play = false
        for i = 1, CardProgressionConstants.EquipmentNum do
            if equipmentList[i] ~= animData[i] then
                self:PlayEquipmentBtnSwitchAnimation(i)
                play = true
            end
        end
        if play then
            UIRaycastBlocker:AddCondition("CardProgressionEquipmentChooseDialog")
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.15))
            UIRaycastBlocker:RemoveCondition("CardProgressionEquipmentChooseDialog")
        end
        self:RefreshEquipmentNode()
    end)
end

