---刷新装备属性
function CardProgressionEquipmentChooseDialog:RefreshEquipAttrs()
    self:RefreshSuitInfo()
    local equipmentAttrsDict = self:GetEquipmentAttrs()
    for i, v in ipairs(CardProgressionConstants.EquipmentMainAttrs) do
        if not self._equipmentAttrNodeList[i] then
            if i == 1 then
                CfUtils.SetActive(self.CultivateOverseaAttributeNode, true)
                self._equipmentAttrNodeList[i] = self.CultivateOverseaAttributeNode
            else
                local node = self.SuitDescAndAttrNodeMask.gameObject:AddChild(self.CultivateOverseaAttributeNode.gameObject)
                self._equipmentAttrNodeList[i] = node
            end
        end
        ---@type CardProgressionAttributeNode
        local env = CfUtils.GetLuaScr(self._equipmentAttrNodeList[i], CardProgressionConstants.EnvPath.CardProgressionAttributeNode)
        if not isNull(env) then
            local attrData = equipmentAttrsDict[v] or {}
            local attrVo = CfUtils.GetCfVo(AutoIds.IdSetting46, "AttrDefinesVo", v)
            local attrNum = attrData.curAttr or 0
            env:FreshUI({
                viewType = CardProgressionConstants.AttrNodeType.Single,
                icon = attrVo.icon,
                name = attrVo.name,
                attrNum = '+' .. attribute_format(attrVo.isConversion, attrNum),
            }, nil, i)
        end
    end
end

function CardProgressionEquipmentChooseDialog:LoadComparedView(curDojo, compareDojo, equipType, part, closeCb)
    if self.ComparedView then
        self:RefreshComparedView(curDojo, compareDojo, equipType, part, closeCb)
        return
    end
    if self.ComparedViewCo then
        return
    end
    self.ComparedViewCo = cs_coroutine.start(function()
        self.ComparedView = GameUtils.LoadBundleAsyncById(EquipComparedViewPrefabId, self.Container.gameObject, false, true)
        self:RefreshComparedView(curDojo, compareDojo, equipType, part, closeCb)
        self.ComparedViewCo = nil
    end)
end

---刷新套装信息
function CardProgressionEquipmentChooseDialog:RefreshSuitInfo()
    local equipmentList = self:GetEquipmentList()
    local equips = {}
    for i, playerEquipmentId in ipairs(equipmentList) do
        if checkInt(playerEquipmentId) > 0 then
            local equipDojo = EquipComponent:GetEquipById(playerEquipmentId) or {}
            equips[i] = equipDojo
        end
    end
    local suits = EquipUtils.GetEquipSuitInfoByEquipDojoList(equips, 2)
    for _, v in ipairs(self._suitNodeList) do
        CfUtils.SetActive(v, false)
    end
    local activeNum = 0
    for k, v in pairs(suits) do
        local suitVo = CfUtils.GetCfVo(AutoIds.IdSetting102, "EquipFilterVo", k)
        if v >= suitVo.suitNum then
            for i = 1, math.floor(v / suitVo.suitNum) do
                activeNum = activeNum + 1
                if not self._suitNodeList[activeNum] then
                    if activeNum == 1 then
                        self._suitNodeList[activeNum] = self.SuitEffectNode.gameObject
                    else
                        local node = self.SuitContent.gameObject:AddChild(self.SuitEffectNode.gameObject)
                        self._suitNodeList[activeNum] = node
                    end
                end
                local node = self._suitNodeList[activeNum]
                CfUtils.SetActive(node, true)
                local icon = node.transform:Find('Icon/ImgAttribute')
                CfUtils.FillImage(icon, suitVo.icon)
                local desc = node.transform:Find('TextDesc')
                CfUtils.FillText(desc, suitVo.desc)
            end
        end
    end
    CfUtils.SetActive(self.SuitEmpty, activeNum == 0)
    CfUtils.SetActive(self.SuitContent, activeNum > 0)
end

