---判断套装是否可用
function CardProgressionEquipmentChooseDialog:IsSuitAvailable()
    local equipmentStr = self:GetFormattingEquipmentStr()
    if equipmentStr == "0,0,0,0,0,0" then
        GameUtils.Toast(localize('套装不能为空'))
        return false
    end

    local name = self.InputField.text
    if name == '' then
        GameUtils.Toast(localize('套装名称不能为空'))
        return false
    end
    
    local equipmentDiySuits = checkTable(PlayerComponent.playerDojo.equipmentDiySuits)
    for _, v in ipairs(equipmentDiySuits) do
        if v.equipments == equipmentStr then
            if next(self:GetSuitData()) and checkInt(self:GetSuitData().suitId) == checkInt(v.suitId) then
                -- 同套装未做修改
                return true
            else
                GameUtils.Toast(localize('套装已存在'))
                return false
            end
        end
    end
    
    return true
end
