---获取格式化装备字符串
function CardProgressionEquipmentChooseDialog:GetFormattingEquipmentStr()
    local equipmentList = self:GetEquipmentList()
    local str = ""
    for i, v in ipairs(equipmentList) do
        str = str .. v
        if i < #equipmentList then
            str = str .. ","
        end
    end
    return str
end

---获取当前卡牌的装备属性加成
function CardProgressionEquipmentChooseDialog:GetEquipmentAttrs()
    local cardDojo               = clone(self:GetCardDojo())
    local basicAttributeDataDict = {}
    local star                   = checkNumber(cardDojo.star)
    local cardLevel              = checkNumber(cardDojo.cardLevel)
    local emptyEquipIdList = {0, 0, 0, 0, 0, 0}
    local equipIdList = self:GetEquipmentList()
    local isOwnEquip = false
    for i, v in ipairs(equipIdList) do
        if checkNumber(v) > 0 then
            isOwnEquip = true
            break
        end
    end

    local preParams = {star = star, cardLevel = cardLevel, equipIdList = emptyEquipIdList, playerEquipCoreId = 0}
    local curParams = {star = star, cardLevel = cardLevel, equipIdList = equipIdList, playerEquipCoreId = 0}
    FormulaUtils.CompareBasicAttrs(cardDojo, cardDojo, function (basicVo, emptyEquipAttr, equipAttr, index)
        local isShowAddAttr = false
        local attrNum = 0
        if isOwnEquip then
            attrNum = equipAttr - emptyEquipAttr
            isShowAddAttr = math.abs(attrNum) > 0
        end
        if isShowAddAttr then
            basicAttributeDataDict[checkInt(basicVo.refId)] = {
                curAttr = attrNum,
                name    = basicVo.name,
                icon    = basicVo.icon,
            }
        end
    end, preParams, curParams)

    return basicAttributeDataDict
end

